import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"Dify","description":"在 Dify 中通过 OpenAI-API-compatible 插件或自定义模型供应商接入 Tokeness。","frontmatter":{"title":"Dify","description":"在 Dify 中通过 OpenAI-API-compatible 插件或自定义模型供应商接入 Tokeness。"},"headers":[],"relativePath":"zh/integrations/dify.md","filePath":"zh/integrations/dify.md","lastUpdated":1783700215000}'),n={name:"zh/integrations/dify.md"};function s(o,e,l,p,r,h){return a(),i("div",null,[...e[0]||(e[0]=[d(`<h1 id="dify" tabindex="-1">Dify <a class="header-anchor" href="#dify" aria-label="Permalink to &quot;Dify&quot;">​</a></h1><p>Dify 可以通过模型供应商接入外部模型。接入 Tokeness 时，使用 Dify 的 OpenAI-API-compatible 插件或 OpenAI 兼容模型供应商，填写 Tokeness 的 API Endpoint、API Key 和模型名。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>Provider</td><td>OpenAI-API-compatible</td></tr><tr><td>API Endpoint / Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model Name</td><td>Tokeness 模型广场中的完整模型名</td></tr></tbody></table><p>如果你的 Dify 版本已经内置 OpenAI Compatible Provider，直接使用内置入口。没有内置入口时，安装 Marketplace 里的 OpenAI-API-compatible 插件。</p><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>先准备：</p><ol><li>Dify 专用 API Key。</li><li>一个聊天模型名。</li><li>如果要做 RAG，再准备一个 embedding 模型名。</li><li>可用余额。</li></ol><p>Key 名称可以写成：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dify-workspace</span></span></code></pre></div><p>生产环境和测试环境分开建 Key。</p><h2 id="_2-安装或打开模型供应商" tabindex="-1">2. 安装或打开模型供应商 <a class="header-anchor" href="#_2-安装或打开模型供应商" aria-label="Permalink to &quot;2. 安装或打开模型供应商&quot;">​</a></h2><p>在 Dify 工作区中进入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Settings -&gt; Model Provider</span></span></code></pre></div><p>如果能看到 OpenAI-API-compatible 或 OpenAI Compatible，直接进入配置。</p><p>如果看不到：</p><ol><li>打开 Dify Marketplace。</li><li>搜索 <code>OpenAI-API-compatible</code>。</li><li>安装 <code>langgenius/openai_api_compatible</code> 插件。</li><li>回到模型供应商设置页。</li></ol><h2 id="_3-添加-tokeness-llm" tabindex="-1">3. 添加 Tokeness LLM <a class="header-anchor" href="#_3-添加-tokeness-llm" aria-label="Permalink to &quot;3. 添加 Tokeness LLM&quot;">​</a></h2><p>在 OpenAI-API-compatible Provider 中添加模型。</p><p>填写：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API Endpoint: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: 你的 Tokeness API Key</span></span>
<span class="line"><span>Model Name: 从 Tokeness 模型广场复制的模型名</span></span></code></pre></div><p>模型类型选择 LLM 或 Chat Model。上下文长度、最大输出、函数调用、多模态等能力按 Tokeness 模型广场和实际测试结果填写。</p><p>如果 Dify 要求填写 Completion mode，普通对话应用优先使用 Chat Completion。</p><h2 id="_4-添加-embedding-模型" tabindex="-1">4. 添加 Embedding 模型 <a class="header-anchor" href="#_4-添加-embedding-模型" aria-label="Permalink to &quot;4. 添加 Embedding 模型&quot;">​</a></h2><p>如果 Dify 应用要使用知识库，需要额外添加 embedding 模型。</p><p>填写方式与聊天模型一致：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API Endpoint: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: 你的 Tokeness API Key</span></span>
<span class="line"><span>Model Name: 从 Tokeness 模型广场复制的 embedding 模型名</span></span></code></pre></div><p>注意：</p><ul><li>聊天模型和 embedding 模型不是同一个东西。</li><li>知识库索引建立后，更换 embedding 模型可能需要重建索引。</li><li>如果只做聊天应用，可以先不配置 embedding。</li></ul><h2 id="_5-在应用中选择模型" tabindex="-1">5. 在应用中选择模型 <a class="header-anchor" href="#_5-在应用中选择模型" aria-label="Permalink to &quot;5. 在应用中选择模型&quot;">​</a></h2><p>进入 Dify 应用的编排页面，在模型选择处选中 Tokeness Provider 下的模型。</p><p>首次测试：</p><ol><li>新建一个空白聊天应用。</li><li>选择 Tokeness 模型。</li><li>输入一句短问题。</li><li>到 Tokeness 使用日志确认请求。</li></ol><p>工作流应用中，每个 LLM 节点都要检查是否选中了 Tokeness 模型。</p><h2 id="_6-自托管-dify-注意事项" tabindex="-1">6. 自托管 Dify 注意事项 <a class="header-anchor" href="#_6-自托管-dify-注意事项" aria-label="Permalink to &quot;6. 自托管 Dify 注意事项&quot;">​</a></h2><p>自托管 Dify 时，Dify 容器需要能访问 <code>https://n.tokeness.io/v1</code>。</p><p>如果验证失败：</p><table tabindex="0"><thead><tr><th>检查项</th><th>说明</th></tr></thead><tbody><tr><td>容器网络</td><td>Dify API/worker 容器能否访问外网</td></tr><tr><td>代理</td><td>服务器是否需要配置 HTTP/HTTPS 代理</td></tr><tr><td>证书</td><td>是否有自签证书或公司网关拦截</td></tr><tr><td>Endpoint</td><td>不要写成本机浏览器能访问但容器不能访问的地址</td></tr></tbody></table><p>可以进入 Dify 容器里用 cURL 测试 Tokeness 接口。</p><h2 id="_7-排查" tabindex="-1">7. 排查 <a class="header-anchor" href="#_7-排查" aria-label="Permalink to &quot;7. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>Credential validation failed</td><td>检查 Endpoint、Key、容器网络</td></tr><tr><td>401 Unauthorized</td><td>API Key 错误或已禁用</td></tr><tr><td>404 Not Found</td><td>API Endpoint 填 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>模型名从 Tokeness 模型广场重新复制</td></tr><tr><td>应用里找不到模型</td><td>模型添加后未保存，或没有在应用节点中选择</td></tr><tr><td>知识库无法索引</td><td>检查 embedding 模型是否配置正确</td></tr><tr><td>Tokeness 无日志</td><td>Dify 当前应用没有使用 Tokeness 模型</td></tr></tbody></table><h2 id="外部文档" tabindex="-1">外部文档 <a class="header-anchor" href="#外部文档" aria-label="Permalink to &quot;外部文档&quot;">​</a></h2><ul><li><a href="https://docs.dify.ai/en/use-dify/workspace/model-providers" target="_blank" rel="noreferrer">Dify Model Providers</a></li><li><a href="https://marketplace.dify.ai/plugin/langgenius/openai_api_compatible" target="_blank" rel="noreferrer">Dify OpenAI-API-compatible Marketplace 插件</a></li></ul>`,43)])])}const k=t(n,[["render",s]]);export{b as __pageData,k as default};
